'use strict';
(()=>{
const choices=[{id:'charcoal',name:'Dark Grey',description:'Quiet charcoal with soft green accents.',accent:'#e3e6eb'},{id:'white',name:'White',description:'Clean white with forest green accents.',accent:'#3c55b8'},{id:'red',name:'Black & Red',description:'Deep black with crimson accents.',accent:'#ff6478'},{id:'blue',name:'Black & Blue',description:'Deep black with cool blue accents.',accent:'#75aaff'},{id:'moss',name:'Original Green',description:'The original moss and lime palette.',accent:'#d4f78b'}];
function apply(id){if(!choices.some(t=>t.id===id))id='charcoal';document.documentElement.dataset.theme=id;const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.setAttribute('content',id==='white'?'#f5f6f8':id==='charcoal'?'#17191c':id==='moss'?'#101311':id==='blue'?'#06080c':'#080608');try{localStorage.setItem('oktawka-theme',id)}catch{}return id}
let saved='charcoal';try{saved=localStorage.getItem('oktawka-theme')||'charcoal'}catch{}apply(saved);
function open(){modal(`<div class="eyebrow">MAKE IT YOURS</div><h2>Your colors. Your Oktawka.</h2><p>Pick a palette for your next listen.</p><div class="theme-choices">${choices.map(t=>`<button class="theme-choice" data-theme-choice="${t.id}" aria-pressed="${document.documentElement.dataset.theme===t.id}" style="--choice-accent:${t.accent}"><div class="theme-swatch"><span></span><i></i><i></i></div><b>${t.name}</b><small>${t.description}</small></button>`).join('')}</div><p class="note">Your choice is remembered on this device.</p><button class="primary" id="theme-done">Done</button>`);document.querySelectorAll('[data-theme-choice]').forEach(button=>button.onclick=()=>{apply(button.dataset.themeChoice);document.querySelectorAll('[data-theme-choice]').forEach(b=>b.setAttribute('aria-pressed',b===button))});document.querySelector('#theme-done').onclick=()=>document.querySelector('#dialog').close()}
document.addEventListener('DOMContentLoaded',()=>{const button=document.querySelector('#theme-switch');if(button)button.onclick=open});
})();
